// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(address caller, bytes32 role) public {
        vm.assume(caller != address(this));
        // reference: renounceRole only revokes, so afterwards the caller never holds the role
        vm.prank(caller);
        c.renounceRole(role, caller);
        assertTrue(!c.hasRole(role, caller));
    }
}
